//! Parsing of human friendly durations ("1h30m", "500ms") and of
//! RFC3339-ish timestamps ("2018-04-20 04:20:00").
//!
//! The grammar and error reporting were derived from black-box testing of
//! the reference binary.

use std::fmt;
use std::str::Chars;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

/// Errors produced while parsing a duration string.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DurationError {
    /// A character that is neither a digit, whitespace nor a letter.
    InvalidCharacter(usize),
    /// A number was expected at the given byte offset.
    NumberExpected(usize),
    /// The unit spanning the given byte range is not recognised.
    UnknownUnit(usize, usize),
    /// Arithmetic overflow while accumulating the value.
    Overflow,
    /// The input contained no number at all.
    Empty,
}

impl fmt::Display for DurationError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match *self {
            DurationError::InvalidCharacter(off) => write!(f, "invalid character at {}", off),
            DurationError::NumberExpected(off) => write!(f, "expected number at {}", off),
            DurationError::UnknownUnit(start, end) => {
                write!(f, "unknown unit at {}-{}", start, end)
            }
            DurationError::Overflow => write!(f, "number is too large"),
            DurationError::Empty => write!(f, "value was empty"),
        }
    }
}

impl std::error::Error for DurationError {}

struct DurationParser<'a> {
    src: &'a str,
    iter: Chars<'a>,
    secs: u64,
    nanos: u64,
}

fn checked_mul(a: u64, b: u64) -> Result<u64, DurationError> {
    a.checked_mul(b).ok_or(DurationError::Overflow)
}

fn checked_add(a: u64, b: u64) -> Result<u64, DurationError> {
    a.checked_add(b).ok_or(DurationError::Overflow)
}

impl<'a> DurationParser<'a> {
    /// Byte offset of the next unread character.
    fn offset(&self) -> usize {
        self.src.len() - self.iter.as_str().len()
    }

    /// Skips whitespace and returns the first digit of the next number.
    fn first_digit(&mut self) -> Result<Option<u64>, DurationError> {
        let off = self.offset();
        for c in self.iter.by_ref() {
            match c {
                '0'..='9' => return Ok(Some(c as u64 - '0' as u64)),
                c if c.is_whitespace() => continue,
                _ => return Err(DurationError::NumberExpected(off)),
            }
        }
        Ok(None)
    }

    fn apply_unit(&mut self, n: u64, start: usize, end: usize) -> Result<(), DurationError> {
        let (mut secs, nanos) = match &self.src[start..end] {
            "nanos" | "nsec" | "ns" => (0u64, n),
            "usec" | "us" => (0u64, checked_mul(n, 1_000)?),
            "millis" | "msec" | "ms" => (0u64, checked_mul(n, 1_000_000)?),
            "seconds" | "second" | "secs" | "sec" | "s" => (n, 0),
            "minutes" | "minute" | "mins" | "min" | "m" => (checked_mul(n, 60)?, 0),
            "hours" | "hour" | "hrs" | "hr" | "h" => (checked_mul(n, 3_600)?, 0),
            "days" | "day" | "d" => (checked_mul(n, 86_400)?, 0),
            "weeks" | "week" | "w" => (checked_mul(n, 7 * 86_400)?, 0),
            "months" | "month" | "M" => (checked_mul(n, 2_630_016)?, 0),
            "years" | "year" | "y" => (checked_mul(n, 31_557_600)?, 0),
            _ => return Err(DurationError::UnknownUnit(start, end)),
        };
        let mut nanos = checked_add(self.nanos, nanos)?;
        if nanos > 1_000_000_000 {
            secs = checked_add(secs, nanos / 1_000_000_000)?;
            nanos %= 1_000_000_000;
        }
        self.secs = checked_add(self.secs, secs)?;
        self.nanos = nanos;
        Ok(())
    }

    fn parse(mut self) -> Result<Duration, DurationError> {
        let mut n = self.first_digit()?.ok_or(DurationError::Empty)?;
        'outer: loop {
            // Remaining digits of the number (whitespace is tolerated).
            let mut off = self.offset();
            while let Some(c) = self.iter.next() {
                match c {
                    '0'..='9' => {
                        n = n
                            .checked_mul(10)
                            .and_then(|x| x.checked_add(c as u64 - '0' as u64))
                            .ok_or(DurationError::Overflow)?;
                    }
                    c if c.is_whitespace() => {}
                    'a'..='z' | 'A'..='Z' => break,
                    _ => return Err(DurationError::InvalidCharacter(off)),
                }
                off = self.offset();
            }
            // The unit.
            let start = off;
            let mut off = self.offset();
            while let Some(c) = self.iter.next() {
                match c {
                    '0'..='9' => {
                        self.apply_unit(n, start, off)?;
                        n = c as u64 - '0' as u64;
                        continue 'outer;
                    }
                    c if c.is_whitespace() => break,
                    'a'..='z' | 'A'..='Z' => {}
                    _ => return Err(DurationError::InvalidCharacter(off)),
                }
                off = self.offset();
            }
            self.apply_unit(n, start, off)?;
            n = match self.first_digit()? {
                Some(n) => n,
                None => return Ok(Duration::new(self.secs, self.nanos as u32)),
            };
        }
    }
}

/// Parses strings such as `5s`, `1h 30m`, `1h1m1s1ms1us`.
pub fn parse_duration(s: &str) -> Result<Duration, DurationError> {
    DurationParser {
        src: s,
        iter: s.chars(),
        secs: 0,
        nanos: 0,
    }
    .parse()
}

/// Errors produced while parsing a timestamp.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TimestampError {
    OutOfRange,
    InvalidDigit,
    InvalidFormat,
}

impl fmt::Display for TimestampError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match *self {
            TimestampError::OutOfRange => write!(f, "numeric component is out of range"),
            TimestampError::InvalidDigit => write!(f, "bad character where digit is expected"),
            TimestampError::InvalidFormat => write!(f, "timestamp format is invalid"),
        }
    }
}

impl std::error::Error for TimestampError {}

fn two_digits(a: u8, b: u8) -> Result<u64, TimestampError> {
    if !a.is_ascii_digit() || !b.is_ascii_digit() {
        return Err(TimestampError::InvalidDigit);
    }
    Ok(((a - b'0') * 10 + (b - b'0')) as u64)
}

fn is_leap_year(y: u64) -> bool {
    y % 4 == 0 && (y % 100 != 0 || y % 400 == 0)
}

/// Parses `YYYY-MM-DD HH:MM:SS[.fraction][Z]` (a `T` may separate date and
/// time).  The timestamp is interpreted as UTC.
pub fn parse_timestamp(s: &str) -> Result<SystemTime, TimestampError> {
    const MIN_LEN: usize = "2018-02-14T00:28:07".len();
    if s.len() < MIN_LEN {
        return Err(TimestampError::InvalidFormat);
    }
    let b = s.as_bytes();
    if b[4] != b'-'
        || b[7] != b'-'
        || (b[10] != b'T' && b[10] != b' ')
        || b[13] != b':'
        || b[16] != b':'
    {
        return Err(TimestampError::InvalidFormat);
    }
    let year = two_digits(b[0], b[1])? * 100 + two_digits(b[2], b[3])?;
    let month = two_digits(b[5], b[6])?;
    let day = two_digits(b[8], b[9])?;
    let hour = two_digits(b[11], b[12])?;
    let minute = two_digits(b[14], b[15])?;
    let mut second = two_digits(b[17], b[18])?;

    if year < 1970 || hour > 23 || minute > 59 || second > 60 {
        return Err(TimestampError::OutOfRange);
    }
    if second == 60 {
        second = 59;
    }
    let leap_years =
        ((year - 1) - 1968) / 4 - ((year - 1) - 1900) / 100 + ((year - 1) - 1600) / 400;
    let leap = is_leap_year(year);
    let (mut ydays, mdays) = match month {
        1 => (0, 31),
        2 if leap => (31, 29),
        2 => (31, 28),
        3 => (59, 31),
        4 => (90, 30),
        5 => (120, 31),
        6 => (151, 30),
        7 => (181, 31),
        8 => (212, 31),
        9 => (243, 30),
        10 => (273, 31),
        11 => (304, 30),
        12 => (334, 31),
        _ => return Err(TimestampError::OutOfRange),
    };
    if day > mdays || day == 0 {
        return Err(TimestampError::OutOfRange);
    }
    ydays += day - 1;
    if leap && month > 2 {
        ydays += 1;
    }
    let days = (year - 1970) * 365 + leap_years + ydays;
    let time = second + minute * 60 + hour * 3600;

    let mut nanos: u32 = 0;
    let mut mult: u32 = 100_000_000;
    if b.get(19) == Some(&b'.') {
        for idx in 20..b.len() {
            if b[idx] == b'Z' {
                if idx == b.len() - 1 {
                    break;
                }
                return Err(TimestampError::InvalidDigit);
            }
            if !b[idx].is_ascii_digit() {
                return Err(TimestampError::InvalidDigit);
            }
            nanos += mult * (b[idx] - b'0') as u32;
            mult /= 10;
        }
    } else if b.len() != 19 && (b.len() > 20 || b[19] != b'Z') {
        return Err(TimestampError::InvalidFormat);
    }

    let total = time + days * 86_400;
    Ok(UNIX_EPOCH + Duration::new(total, nanos))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn durations() {
        assert_eq!(parse_duration("5s"), Ok(Duration::from_secs(5)));
        assert_eq!(parse_duration("1h1m1s1ms1us"), Ok(Duration::new(3661, 1_001_000)));
        assert_eq!(parse_duration("5"), Err(DurationError::UnknownUnit(1, 1)));
        assert_eq!(parse_duration("5x"), Err(DurationError::UnknownUnit(1, 2)));
        assert_eq!(parse_duration("abc"), Err(DurationError::NumberExpected(0)));
        assert_eq!(parse_duration(""), Err(DurationError::Empty));
        assert_eq!(parse_duration("1.5s"), Err(DurationError::InvalidCharacter(1)));
        assert_eq!(parse_duration("1 s 1"), Err(DurationError::UnknownUnit(5, 5)));
        assert_eq!(parse_duration("1s abc"), Err(DurationError::NumberExpected(3)));
        assert_eq!(parse_duration("999999999999y"), Err(DurationError::Overflow));
    }

    #[test]
    fn timestamps() {
        assert!(parse_timestamp("2018-04-20 04:20:00").is_ok());
        assert!(parse_timestamp("2018-04-20T04:20:00Z").is_ok());
        assert_eq!(parse_timestamp("2018-04-20"), Err(TimestampError::InvalidFormat));
        assert_eq!(parse_timestamp("1969-04-20 04:20:00"), Err(TimestampError::OutOfRange));
        assert_eq!(parse_timestamp("2018-04-20 04:20:0a"), Err(TimestampError::InvalidDigit));
        assert_eq!(
            parse_timestamp("1970-01-01 00:00:00").unwrap(),
            UNIX_EPOCH
        );
    }
}
EOF
echo done"}

