//! Command line parsing.
//!
//! A small, purpose built option parser whose observable behaviour (help
//! text, error wording, usage hints, "did you mean" suggestions) mirrors the
//! reference implementation.

use std::collections::HashMap;
use std::io::IsTerminal;
use std::path::Path;
use std::process;

use crate::similarity::best_match;

pub const APP_NAME: &str = "loop";
pub const VERSION: &str = "0.6.1";

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    Flag,
    Option,
}

pub type Validator = fn(&str) -> Result<(), String>;

pub struct ArgSpec {
    /// Internal identifier; also used as the value placeholder.
    pub name: &'static str,
    pub short: Option<char>,
    pub long: &'static str,
    pub kind: Kind,
    pub default: Option<&'static str>,
    pub validator: Option<Validator>,
}

impl ArgSpec {
    /// The way the argument is referred to in messages: `--num <num>`.
    pub fn display(&self) -> String {
        match self.kind {
            Kind::Flag => format!("--{}", self.long),
            Kind::Option => format!("--{} <{}>", self.long, self.name),
        }
    }
}

fn validate_float(s: &str) -> Result<(), String> {
    s.parse::<f64>().map(|_| ()).map_err(|e| e.to_string())
}

fn validate_duration(s: &str) -> Result<(), String> {
    crate::timeparse::parse_duration(s)
        .map(|_| ())
        .map_err(|e| e.to_string())
}

fn validate_timestamp(s: &str) -> Result<(), String> {
    crate::timeparse::parse_timestamp(s)
        .map(|_| ())
        .map_err(|e| e.to_string())
}

fn validate_regex(s: &str) -> Result<(), String> {
    regex::Regex::new(s).map(|_| ()).map_err(|e| e.to_string())
}

/// Flags, in the order they are consulted for suggestions.
pub const FLAGS: &[ArgSpec] = &[
    ArgSpec { name: "only_last", short: Some('l'), long: "only-last", kind: Kind::Flag, default: None, validator: None },
    ArgSpec { name: "stdin", short: Some('i'), long: "stdin", kind: Kind::Flag, default: None, validator: None },
    ArgSpec { name: "until_changes", short: Some('C'), long: "until-changes", kind: Kind::Flag, default: None, validator: None },
    ArgSpec { name: "until_same", short: Some('S'), long: "until-same", kind: Kind::Flag, default: None, validator: None },
    ArgSpec { name: "until_success", short: Some('s'), long: "until-success", kind: Kind::Flag, default: None, validator: None },
    ArgSpec { name: "until_fail", short: Some('f'), long: "until-fail", kind: Kind::Flag, default: None, validator: None },
    ArgSpec { name: "summary", short: None, long: "summary", kind: Kind::Flag, default: None, validator: None },
    ArgSpec { name: "error_duration", short: Some('D'), long: "error-duration", kind: Kind::Flag, default: None, validator: None },
    ArgSpec { name: "help", short: Some('h'), long: "help", kind: Kind::Flag, default: None, validator: None },
    ArgSpec { name: "version", short: Some('V'), long: "version", kind: Kind::Flag, default: None, validator: None },
];

/// Options taking a value, in the order they are consulted for suggestions.
pub const OPTIONS: &[ArgSpec] = &[
    ArgSpec { name: "count_by", short: Some('b'), long: "count-by", kind: Kind::Option, default: Some("1"), validator: Some(validate_float) },
    ArgSpec { name: "every", short: Some('e'), long: "every", kind: Kind::Option, default: Some("1us"), validator: Some(validate_duration) },
    ArgSpec { name: "ffor", short: None, long: "for", kind: Kind::Option, default: None, validator: None },
    ArgSpec { name: "for_duration", short: Some('d'), long: "for-duration", kind: Kind::Option, default: None, validator: Some(validate_duration) },
    ArgSpec { name: "num", short: Some('n'), long: "num", kind: Kind::Option, default: None, validator: Some(validate_float) },
    ArgSpec { name: "offset", short: Some('o'), long: "offset", kind: Kind::Option, default: Some("0"), validator: Some(validate_float) },
    ArgSpec { name: "until_contains", short: Some('c'), long: "until-contains", kind: Kind::Option, default: None, validator: None },
    ArgSpec { name: "until_error", short: Some('r'), long: "until-error", kind: Kind::Option, default: None, validator: None },
    ArgSpec { name: "until_match", short: Some('m'), long: "until-match", kind: Kind::Option, default: None, validator: Some(validate_regex) },
    ArgSpec { name: "until_time", short: Some('t'), long: "until-time", kind: Kind::Option, default: None, validator: Some(validate_timestamp) },
];

pub const POSITIONAL: &str = "input";

const HELP_BODY: &str = "\
FLAGS:
    -D, --error-duration    Exit with timeout error code on duration
    -h, --help              Prints help information
    -l, --only-last         Only print the output of the last execution of the command
    -i, --stdin             Read from standard input
        --summary           Provide a summary
    -C, --until-changes     Keep going until the output changes
    -f, --until-fail        Keep going until the command exit status is non-zero
    -S, --until-same        Keep going until the output changes
    -s, --until-success     Keep going until the command exit status is zero
    -V, --version           Prints version information

OPTIONS:
    -b, --count-by <count_by>                Amount to increment the counter by [default: 1]
    -e, --every <every>                      How often to iterate. ex., 5s, 1h1m1s1ms1us [default: 1us]
        --for <ffor>                         A comma-separated list of values, placed into 4ITEM. ex., red,green,blue
    -d, --for-duration <for_duration>        Keep going until the duration has elapsed (example 1m30s)
    -n, --num <num>                          Number of iterations to execute
    -o, --offset <offset>                    Amount to offset the initial counter by [default: 0]
    -c, --until-contains <until_contains>    Keep going until the output contains this string
    -r, --until-error <until_error>          Keep going until the command exit status is the value given
    -m, --until-match <until_match>          Keep going until the output matches this regular expression
    -t, --until-time <until_time>            Keep going until a future time, ex. \"2018-04-20 04:20:00\" (Times in UTC.)

ARGS:
    <input>...    The command to be looped";

fn find_opt_by_long(long: &str) -> Option<&'static ArgSpec> {
    OPTIONS.iter().find(|a| a.long == long)
}

fn find_flag_by_long(long: &str) -> Option<&'static ArgSpec> {
    FLAGS.iter().find(|a| a.long == long)
}

fn find_opt_by_short(c: char) -> Option<&'static ArgSpec> {
    OPTIONS.iter().find(|a| a.short == Some(c))
}

fn find_flag_by_short(c: char) -> Option<&'static ArgSpec> {
    FLAGS.iter().find(|a| a.short == Some(c))
}

fn find_by_name(name: &str) -> Option<&'static ArgSpec> {
    FLAGS
        .iter()
        .chain(OPTIONS.iter())
        .find(|a| a.name == name)
}

/// Terminal colouring for diagnostics (only when stderr is a terminal).
struct Painter {
    enabled: bool,
}

impl Painter {
    fn detect() -> Painter {
        let dumb = std::env::var("TERM").ok().as_deref() == Some("dumb");
        Painter {
            enabled: std::io::stderr().is_terminal() && !dumb,
        }
    }

    fn error(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[1;31m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }

    fn warning(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[33m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }

    fn good(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[32m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
}

/// Always-green text, used by the suggestion hint.
fn always_good(s: &str) -> String {
    format!("\x1b[32m{}\x1b[0m", s)
}

#[derive(Default, Debug)]
pub struct Matched {
    pub occurrences: usize,
    pub values: Vec<String>,
}

#[derive(Debug)]
pub struct Matches {
    pub args: HashMap<&'static str, Matched>,
    pub input: Vec<String>,
}

impl Matches {
    pub fn is_present(&self, name: &str) -> bool {
        self.args.contains_key(name)
    }

    pub fn value_of(&self, name: &str) -> Option<&str> {
        self.args
            .get(name)
            .and_then(|m| m.values.first())
            .map(|s| s.as_str())
    }
}

enum Pending {
    None,
    /// An option that still expects its value from the next argument.
    Value(&'static ArgSpec),
}

pub struct Parser {
    bin_name: String,
    painter: Painter,
    matches: Matches,
}

impl Parser {
    fn new(bin_name: String) -> Parser {
        Parser {
            bin_name,
            painter: Painter::detect(),
            matches: Matches {
                args: HashMap::new(),
                input: Vec::new(),
            },
        }
    }

    fn entry(&mut self, spec: &'static ArgSpec) -> &mut Matched {
        self.matches.args.entry(spec.name).or_default()
    }

    fn record_flag(&mut self, spec: &'static ArgSpec) {
        self.entry(spec).occurrences += 1;
    }

    fn record_value(&mut self, spec: &'static ArgSpec, value: &str) {
        let m = self.entry(spec);
        m.values.push(value.to_string());
        m.occurrences += 1;
    }

    /// The full usage line, shown when nothing more specific is known.
    fn full_usage(&self) -> String {
        format!("{} [FLAGS] [OPTIONS] [{}]...", self.bin_name, POSITIONAL)
    }

    /// Usage mentioning the arguments that were seen so far.
    fn usage(&self) -> String {
        let mut names: Vec<&str> = self
            .matches
            .args
            .keys()
            .copied()
            .filter(|n| find_by_name(n).is_some())
            .collect();
        if names.is_empty() {
            return format!("USAGE:\n    {}", self.full_usage());
        }
        names.sort();
        names.dedup();
        let mut usage = format!("USAGE:\n    {}", self.bin_name);
        for n in names {
            if let Some(spec) = find_by_name(n) {
                usage.push(' ');
                usage.push_str(&spec.display());
            }
        }
        usage
    }

    fn fail(&self, message: String) -> ! {
        eprintln!("{}", message);
        process::exit(1);
    }

    fn unknown_argument(&self, arg: &str, suggestion: &str) -> ! {
        let hint = if suggestion.is_empty() {
            "\n".to_string()
        } else {
            format!("{}\n", suggestion)
        };
        self.fail(format!(
            "{} Found argument '{}' which wasn't expected, or isn't valid in this context{}\n{}\n\nFor more information try {}",
            self.painter.error("error:"),
            self.painter.warning(arg),
            hint,
            self.usage(),
            self.painter.good("--help")
        ))
    }

    fn empty_value(&self, spec: &ArgSpec) -> ! {
        self.fail(format!(
            "{} The argument '{}' requires a value but none was supplied\n\n{}\n\nFor more information try {}",
            self.painter.error("error:"),
            self.painter.warning(&spec.display()),
            self.usage(),
            self.painter.good("--help")
        ))
    }

    fn multiple_usage(&self, spec: &ArgSpec) -> ! {
        self.fail(format!(
            "{} The argument '{}' was provided more than once, but cannot be used multiple times\n\n{}\n\nFor more information try {}",
            self.painter.error("error:"),
            self.painter.warning(&spec.display()),
            self.usage(),
            self.painter.good("--help")
        ))
    }

    fn invalid_value(&self, spec: &ArgSpec, err: &str) -> ! {
        self.fail(format!(
            "{} Invalid value for '{}': {}",
            self.painter.error("error:"),
            self.painter.warning(&spec.display()),
            err
        ))
    }

    fn print_help_and_exit(&self) -> ! {
        println!(
            "{} {}\nRich Jones <miserlou@gmail.com>\nUNIX's missing `loop` command\n\nUSAGE:\n    {}\n\n{}",
            APP_NAME,
            VERSION,
            self.full_usage(),
            HELP_BODY
        );
        process::exit(0);
    }

    fn print_version_and_exit(&self) -> ! {
        println!("{} {}", APP_NAME, VERSION);
        process::exit(0);
    }

    fn check_help_version(&self, spec: &ArgSpec) {
        if spec.name == "help" {
            self.print_help_and_exit();
        }
        if spec.name == "version" {
            self.print_version_and_exit();
        }
    }

    /// Handles `--long`, `--long=value`.
    fn parse_long(&mut self, raw: &str) -> Pending {
        let trimmed = raw.trim_start_matches('-');
        let (name, value) = match trimmed.find('=') {
            Some(i) => (&trimmed[..i], Some(&trimmed[i + 1..])),
            None => (trimmed, None),
        };
        if let Some(opt) = find_opt_by_long(name) {
            return match value {
                Some(v) => {
                    self.record_value(opt, v.trim_start_matches('='));
                    Pending::None
                }
                None => {
                    self.record_flag(opt);
                    Pending::Value(opt)
                }
            };
        }
        if let Some(flag) = find_flag_by_long(name) {
            self.check_help_version(flag);
            self.record_flag(flag);
            return Pending::None;
        }
        // Unknown: look for something similar to suggest.
        let longs = FLAGS.iter().chain(OPTIONS.iter()).map(|a| a.long);
        let mut suggestion = String::new();
        if let Some(candidate) = best_match(name, longs) {
            suggestion = format!(
                "\n\tDid you mean {}{}?",
                always_good("--"),
                always_good(candidate)
            );
            if let Some(spec) = find_opt_by_long(candidate).or_else(|| find_flag_by_long(candidate)) {
                self.entry(spec);
            }
        }
        self.unknown_argument(&format!("--{}", name), &suggestion)
    }

    /// Handles `-f`, `-fs`, `-n3`, `-n=3`, `-fn3`.
    fn parse_short(&mut self, raw: &str) -> Pending {
        let trimmed = raw.trim_start_matches('-');
        let mut result = Pending::None;
        for (idx, c) in trimmed.char_indices() {
            if let Some(opt) = find_opt_by_short(c) {
                let rest = &trimmed[idx + c.len_utf8()..];
                if !rest.is_empty() {
                    self.record_value(opt, rest.trim_start_matches('='));
                    return Pending::None;
                }
                self.record_flag(opt);
                return Pending::Value(opt);
            } else if let Some(flag) = find_flag_by_short(c) {
                self.check_help_version(flag);
                self.record_flag(flag);
                result = Pending::None;
            } else {
                self.unknown_argument(&format!("-{}", c), "");
            }
        }
        result
    }

    fn parse_args<I>(mut self, args: I) -> Matches
    where
        I: IntoIterator<Item = String>,
    {
        let mut pending = Pending::None;
        let mut trailing = false;

        for arg in args {
            if !trailing {
                if arg.starts_with("--") {
                    if arg.len() == 2 {
                        trailing = true;
                        continue;
                    }
                    pending = self.parse_long(&arg);
                    continue;
                } else if arg.starts_with('-') && arg.len() != 1 {
                    pending = self.parse_short(&arg);
                    continue;
                } else if let Pending::Value(opt) = pending {
                    let m = self.entry(opt);
                    m.values.push(arg);
                    pending = Pending::None;
                    continue;
                }
            }
            self.matches.input.push(arg);
        }

        // An option at the very end that never received its value.
        if let Pending::Value(opt) = pending {
            self.add_defaults();
            let empty = self
                .matches
                .args
                .get(opt.name)
                .map_or(true, |m| m.values.is_empty());
            if empty {
                self.empty_value(opt);
            }
        } else {
            self.add_defaults();
        }

        self.validate();
        self.matches
    }

    fn add_defaults(&mut self) {
        for spec in OPTIONS {
            if let Some(d) = spec.default {
                if !self.matches.args.contains_key(spec.name) {
                    let m = self.entry(spec);
                    m.values.push(d.to_string());
                }
            }
        }
    }

    fn validate(&self) {
        for (name, m) in self.matches.args.iter() {
            let spec = match find_by_name(name) {
                Some(s) => s,
                None => continue,
            };
            match spec.kind {
                Kind::Option => {
                    if m.values.is_empty() {
                        self.empty_value(spec);
                    }
                    if let Some(validator) = spec.validator {
                        for v in &m.values {
                            if let Err(e) = validator(v) {
                                self.invalid_value(spec, &e);
                            }
                        }
                    }
                    if m.occurrences > 1 {
                        self.multiple_usage(spec);
                    }
                }
                Kind::Flag => {
                    if m.occurrences > 1 {
                        self.multiple_usage(spec);
                    }
                }
            }
        }
    }
}

/// Derives the program name shown in usage from `argv[0]`.
fn bin_name_from(argv0: Option<&std::ffi::OsString>) -> String {
    argv0
        .and_then(|a| Path::new(a).file_name().map(|f| f.to_os_string()))
        .and_then(|f| f.into_string().ok())
        .unwrap_or_else(|| APP_NAME.to_string())
}

/// Parses the process arguments, exiting on error or on `--help`/`--version`.
pub fn parse() -> Matches {
    let mut raw = std::env::args_os();
    let bin_name = bin_name_from(raw.next().as_ref());
    let args: Vec<String> = raw.map(|a| a.to_string_lossy().into_owned()).collect();
    Parser::new(bin_name).parse_args(args)
}
EOF
echo done"}

