//! reference implementation.

use std::collections::HashMap;
use std::io::IsTerminal;
use std::path::Path;
use std::process;

use crate::similarity::best_match;

pub const APP_NAME: &str = "loop";
pub const VERSION: &str = "0.6.1";

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    Flag,
    Option,
}

pub type Validator = fn(&str) -> Result<(), String>;

pub struct ArgSpec {
    /// Internal identifier; also used as the value placeholder.
    pub name: &'static str,
    pub short: Option<char>,
    pub long: &'static str,
    pub kind: Kind,
    pub default: Option<&'static str>,
    pub validator: Option<Validator>,
}

impl ArgSpec {
    /// The way the argument is referred to in messages: `--num <num>`.
    pub fn display(&self) -> String {
        match self.kind {
            Kind::Flag => format!("--{}", self.long),
            Kind::Option => format!("--{} <{}>", self.long, self.name),
        }
    }
}

fn validate_float(s: &str) -> Result<(), String> {
    s.parse::<f64>().map(|_| ()).map_err(|e| e.to_string())
}

fn validate_duration(s: &str) -> Result<(), String> {
    crate::timeparse::parse_duration(s)
        .map(|_| ())
        .map_err(|e| e.to_string())
}

fn validate_timestamp(s: &str) -> Result<(), String> {
    crate::timeparse::parse_timestamp(s)
        .map(|_| ())
        .map_err(|e| e.to_string())
}

fn validate_regex(s: &str) -> Result<(), String> {
    regex::Regex::new(s).map(|_| ()).map_err(|e| e.to_string())
}

