//! `loop` - UNIX's missing `loop` command.
//!
//! Repeatedly runs a shell command with timers, counters and stop conditions.

mod cli;
mod similarity;
mod timeparse;

use std::fs::{self, File, OpenOptions};
use std::io::{self, IsTerminal, Read, Seek, SeekFrom};
use std::os::unix::fs::OpenOptionsExt;
use std::process::{self, Command, ExitStatus, Stdio};
use std::thread;
use std::time::{Duration, Instant, SystemTime};

use regex::Regex;

/// Exit status reported in the summary for commands killed by a signal.
const SIGNAL_EXIT_CODE: i32 = 99;
/// Exit status used with `--error-duration` once the duration has elapsed.
const TIMEOUT_EXIT_CODE: i32 = 124;

/// What `--until-error` is waiting for.
#[derive(Clone, Copy)]
enum ErrorCondition {
    /// Any unsuccessful exit.
    Any,
    /// A specific exit code.
    Code(u32),
}

impl ErrorCondition {
    fn parse(s: &str) -> ErrorCondition {
        match s.parse::<u32>() {
            Ok(code) => ErrorCondition::Code(code),
            Err(_) => ErrorCondition::Any,
        }
    }

    fn satisfied_by(self, status: &ExitStatus) -> bool {
        match self {
            ErrorCondition::Any => !status.success(),
            ErrorCondition::Code(code) => status.code() == Some(code as i32),
        }
    }
}

/// Reads all of standard input and splits it into lines.
fn read_stdin_items() -> Vec<String> {
    let mut buffer = String::new();
    io::stdin().read_to_string(&mut buffer).unwrap();
    buffer.lines().map(str::to_owned).collect()
}

/// Number of decimal digits in the textual representation of a number,
/// e.g. `0.25` -> 2, `1` -> 0, `1.5e3` -> 1.
fn decimal_places(text: &str) -> usize {
    match text.find('.') {
        Some(dot) => text[dot + 1..]
            .chars()
            .take_while(|c| c.is_ascii_digit())
            .count(),
        None => 0,
    }
}

/// Tiny xorshift generator for temporary file names.
struct Rng(u64);

impl Rng {
    fn seeded() -> Rng {
        let nanos = SystemTime::now()
            .duration_since(SystemTime::UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64)
            .unwrap_or(0x9e37_79b9_7f4a_7c15);
        let mixed = nanos ^ ((process::id() as u64) << 32) ^ 0x2545_f491_4f6c_dd1d;
        Rng(if mixed == 0 { 1 } else { mixed })
    }

    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }

    fn alphanumeric(&mut self, len: usize) -> String {
        const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
        (0..len)
            .map(|_| CHARS[(self.next() % CHARS.len() as u64) as usize] as char)
            .collect()
    }
}

/// Creates an anonymous temporary file in the system temp directory.  The
/// file is unlinked right away; it lives for as long as the handle does.
fn anonymous_tempfile(rng: &mut Rng) -> File {
    let dir = std::env::temp_dir();
    loop {
        let path = dir.join(format!(".tmp{}", rng.alphanumeric(6)));
        match OpenOptions::new()
            .read(true)
            .write(true)
            .create_new(true)
            .mode(0o600)
            .open(&path)
        {
            Ok(file) => {
                let _ = fs::remove_file(&path);
                return file;
            }
            Err(e) if e.kind() == io::ErrorKind::AlreadyExists => continue,
            Err(e) => panic!("failed to create temporary file: {}", e),
        }
    }
}

/// Runs `command` through `sh -c`, capturing stdout and stderr together.
fn run_command(command: &str, env: &[(&str, String)], rng: &mut Rng) -> (ExitStatus, String) {
    let capture = anonymous_tempfile(rng);
    let out = capture.try_clone().expect("failed to duplicate capture file");
    let err = capture.try_clone().expect("failed to duplicate capture file");

    let mut child = Command::new("sh");
    child.arg("-c").arg(command);
    for (key, value) in env {
        child.env(key, value);
    }
    let status = child
        .stdout(Stdio::from(out))
        .stderr(Stdio::from(err))
        .status()
        .expect("failed to execute command");

    let mut capture = capture;
    capture.seek(SeekFrom::Start(0)).expect("seek failed");
    let mut output = String::new();
    capture.read_to_string(&mut output).expect("read failed");
    (status, output)
}

struct Summary {
    successes: usize,
    failures: Vec<i32>,
}

impl Summary {
    fn record(&mut self, status: &ExitStatus) {
        if status.success() {
            self.successes += 1;
        } else {
            self.failures.push(status.code().unwrap_or(SIGNAL_EXIT_CODE));
        }
    }

    fn print(&self) {
        println!("Total runs:\t{}", self.successes + self.failures.len());
        println!("Successes:\t{}", self.successes);
        if self.failures.is_empty() {
            println!("Failures:\t0");
        } else {
            let codes: Vec<String> = self.failures.iter().map(|c| c.to_string()).collect();
            println!("Failures:\t{} ({})", self.failures.len(), codes.join(", "));
        }
    }
}

