/// Runs `command` through `sh -c` with stdout and stderr redirected to a
/// fresh temporary file.  Standard input is inherited from this process, as
/// is the environment (see the `COUNT`, `ACTUALCOUNT` and `ITEM` variables).
fn execute(command: &str, rng: &mut Rng) -> Execution {
